window.docContents[127].resolve({"/rules/RG1002/#RG1002-rationale":{"contents":"sorryAx proves every proposition. A declaration that depends on it has no evidence, even if Lean elaborated the file, and every theorem that uses it inherits the gap.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1002: Proof holes are forbidden","header":"Why it matters","id":"/rules/RG1002/#RG1002-rationale"},"/rules/RG2001/#RG2001-rationale":{"contents":"Every conformance claim is about one exact elaboration environment: toolchain, dependency revisions and source state. A result under an unknown or different environment is not evidence for the declared one.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2001: The declared Lean environment must be available","header":"Why it matters","id":"/rules/RG2001/#RG2001-rationale"}});